document.addEventListener("DOMContentLoaded",t=>{document.querySelectorAll("*[data-include]").forEach(t=>{const e=t.getAttribute("data-include"),n=t.getAttribute("data-update"),a=t.getAttribute("data-stop-when");let d,r=!1;const c=()=>{fetch(e).then(e=>{e.text().then(e=>{t.innerHTML=e,null!==a&&e.trim()===a&&(r=!0,void 0!==d&&clearInterval(d))})})};if(c(),n){const t=parseInt(n,10);!isNaN(t)&&t>0&&!r&&(d=setInterval(c,1e3*t))}})});